import Link from "next/link"; import { Activity, HeartPulse, ShieldCheck, Sparkles } from "lucide-react"; import { Calculator } from "@/components/calculator"; import { Definition, FAQ, Section } from "@/components/ui"; import { JsonLd } from "@/lib/schema"; import { site } from "@/lib/site";
const faqs=[{q:"What is a healthy BMI for adults?",a:"For most adults, a BMI from 18.5 to 24.9 is classified as healthy weight. BMI is a screening tool, so a clinician may also consider waist circumference, medical history, fitness, and other measures."},{q:"How is BMI calculated?",a:"Metric BMI is weight in kilograms divided by height in metres squared. In imperial units, multiply weight in pounds by 703 and divide by height in inches squared."},{q:"Is BMI accurate for athletes?",a:"It can be less informative for very muscular people because BMI cannot distinguish muscle from fat. Body composition, waist measurement, and clinical assessment can add useful context."},{q:"Can children use this calculator?",a:"No. Children and teens use BMI-for-age percentiles that account for age and sex, rather than adult BMI categories."},{q:"Does BMI differ for men and women?",a:"The standard adult cutoffs are the same. However, body composition and health risk can differ by sex, age, ethnicity, and individual health factors."}];
export default function Home(){const faqSchema={"@context":"https://schema.org","@type":"FAQPage",mainEntity:faqs.map(x=>({"@type":"Question",name:x.q,acceptedAnswer:{"@type":"Answer",text:x.a}}))};return <><JsonLd data={[faqSchema,{"@context":"https://schema.org","@type":"MedicalWebPage",name:"BMI Calculator",url:site.url,about:{"@type":"MedicalCondition",name:"Body weight assessment"},lastReviewed:"2026-07-24"}]}/><section className="overflow-hidden bg-[radial-gradient(circle_at_80%_10%,#c8f1e3,transparent_32%),linear-gradient(180deg,#f9fefd,#eaf7f3)]"><div className="container grid gap-10 py-16 md:grid-cols-[1.05fr_.95fr] md:py-24"><div className="self-center"><p className="text-sm font-bold uppercase tracking-[.18em] text-teal-700">Evidence-informed health screening</p><h1 className="mt-4 text-5xl font-extrabold tracking-[-.055em] md:text-6xl">BMI Calculator for clear, practical health context.</h1><p className="mt-6 max-w-xl text-lg leading-8 text-slate-600">Calculate your Body Mass Index in seconds, understand the adult BMI category, and see the weight range associated with your height.</p><div className="mt-8 flex flex-wrap gap-3"><Link href="/bmi-calculator" className="rounded-xl bg-teal-700 px-5 py-3 font-bold text-white shadow-lg shadow-teal-900/15">Calculate your BMI</Link><a href="#guide" className="rounded-xl border border-slate-300 bg-white px-5 py-3 font-bold">Read the BMI guide</a></div><p className="mt-6 text-xs text-slate-500">For adults 18+. Educational use only; not a medical diagnosis.</p></div><div className="card p-4 sm:p-6"><h2 className="text-xl font-bold">Quick BMI calculator</h2><p className="mt-1 text-sm text-slate-500">Results update as you type.</p><div className="mt-5"><Calculator compact/></div></div></div></section><Section eyebrow="Why use it" title="A simple number, used with good judgment."><div className="mt-9 grid gap-5 md:grid-cols-3">{[[Activity,"Fast, unit-flexible calculation","Use centimetres and kilograms, or feet, inches, and pounds. Your result appears without a page reload."],[HeartPulse,"More than a category","See the healthy-weight range for your height alongside a plain-language explanation of what BMI can and cannot say."],[ShieldCheck,"Privacy-minded by design","Recent results remain in your browser. We do not ask for a name, account, or health record."]].map(([Icon,title,text])=>{const I=Icon as typeof Activity;return <div className="card p-6" key={title as string}><I className="text-teal-700"/><h3 className="mt-5 text-lg font-bold">{title as string}</h3><p className="mt-2 leading-7 text-slate-600 dark:text-slate-300">{text as string}</p></div>})}</div></Section><Section eyebrow="The essential answer" title="What is BMI?"><Definition><strong>Body Mass Index (BMI)</strong> is a weight-for-height screening measure. For adults, it is calculated from weight and height and grouped into broad categories that can help flag possible health risk. It does not measure body fat directly.</Definition><article id="guide" className="prose-health mt-8 max-w-4xl"><p>BMI is one of the most familiar numbers in preventive health. It is used in clinics, public-health research, and everyday healthy weight calculators because it is inexpensive, reproducible, and easy to understand. The number is useful precisely because it is simple: it relates body weight to height. But that simplicity is also its limit. A BMI result is a starting point for a conversation about health, not a verdict on a person’s health, appearance, or worth.</p><h2>BMI formula: metric and imperial</h2><p>The metric BMI formula is weight in kilograms divided by height in metres squared. If someone weighs 70 kg and is 1.70 m tall, their calculation is 70 ÷ (1.70 × 1.70), or 24.2. The imperial formula uses pounds and inches: weight in pounds × 703 ÷ height in inches squared. Both produce the same BMI Index when the measurements are converted correctly.</p><div className="overflow-x-auto"><table className="mt-5 w-full border-collapse text-left text-sm"><thead><tr className="border-b"><th className="p-3">Adult BMI</th><th className="p-3">Category</th><th className="p-3">General interpretation</th></tr></thead><tbody>{[["Below 18.5","Underweight","May need individual assessment"],["18.5–24.9","Healthy weight","Generally lowest population-level risk"],["25.0–29.9","Overweight","Potentially increased risk"],["30.0 and above","Obesity","Increased risk; support may help"]].map(r=><tr className="border-b" key={r[0]}>{r.map(c=><td className="p-3" key={c}>{c}</td>)}</tr>)}</tbody></table></div><h2>Why clinicians use BMI categories</h2><p>At the population level, BMI categories are associated with different rates of conditions such as type 2 diabetes, high blood pressure, sleep apnoea, and cardiovascular disease. This makes BMI a helpful first screen. In an individual appointment, a clinician may pair it with blood pressure, blood tests, waist circumference, family history, medications, diet, physical activity, and the direction of weight change over time.</p><p>A single BMI cannot tell you whether you have a medical condition. Nor can it tell you where weight is carried. Abdominal fat is particularly relevant to cardiometabolic risk, which is why a waist measurement can be helpful. If your BMI result is unexpected, sudden, or worrying, it deserves context rather than self-judgment.</p><h2>BMI scale and healthy body weight</h2><p>The usual adult BMI scale identifies 18.5 to 24.9 as the healthy weight range. Our calculator translates that range into a practical weight interval for your height. That interval is not an “ideal” body shape and it is not a target to pursue at all costs. Healthy body weight looks different across life stages, cultures, body frames, and medical histories. For many adults, improving blood pressure, stamina, sleep, or food habits matters more than reaching a particular number on the scale.</p><h2>BMI for women and BMI for men</h2><p>Standard adult BMI categories are the same for women and men. Nonetheless, people with the same BMI can have different proportions of fat and lean tissue. Hormonal changes, pregnancy, menopause, and life stage can shape weight distribution for women. Men may carry more weight around the abdomen. These differences are reasons to broaden the health picture, not reasons to treat the calculation as irrelevant. Visit our <Link href="/bmi-women" className="text-teal-700 underline">BMI for women guide</Link> or <Link href="/bmi-men" className="text-teal-700 underline">BMI for men guide</Link> for a fuller discussion.</p><h2>BMI by age: adults, seniors, and children</h2><p>For adults, the categories do not change with age. In later life, however, unintentional weight loss, reduced muscle mass, falls, chronic illness, and frailty make the story more nuanced. Older adults benefit from individualized advice that protects strength, protein intake, mobility, and independence. BMI for children is different again. Children and teenagers are assessed using BMI-for-age growth charts and percentiles, not adult cutoffs. A paediatric clinician can interpret those charts in the context of growth and development.</p><h2>When BMI is less informative</h2><p>Athletes and people with substantial muscle mass can have a higher BMI without having excess body fat. Pregnancy, fluid retention, limb loss, and some medical conditions can also affect the meaning of the number. Ethnicity can matter as well: some populations experience metabolic risks at lower BMI levels. The best next step may be a clinician’s assessment, waist measurement, body-composition test, or simply a discussion of symptoms and lifestyle.</p><h2>BMI versus body fat percentage</h2><p>BMI uses only height and weight. Body fat percentage estimates how much of body weight is fat tissue. That extra detail can be useful, but measurement methods vary in accuracy. Home scales using bioelectrical impedance can change with hydration. Skinfold measurements and DEXA scans require technique or equipment. For most people, a consistent trend in multiple measures is more useful than a single supposedly perfect number.</p><h2>A healthy weight plan built around habits</h2><p>If you would like to gain, lose, or maintain weight, begin with habits you can repeat. Eat regular meals with vegetables or fruit, fibre-rich carbohydrates, protein, and fats that fit your culture and budget. Make water your default drink. Plan movement you enjoy: brisk walking, cycling, swimming, dancing, or strength training all count. Adults generally benefit from at least 150 minutes a week of moderate activity, plus muscle-strengthening work on two or more days, if appropriate for their health.</p><p>Rapid, restrictive plans often backfire. A safer approach is gradual change, adequate sleep, and support from a registered dietitian or clinician when needed. Do not use a BMI result to skip meals, overexercise, or start a supplement. If eating, weight, or body image feels distressing, compassionate professional support is available.</p><h2>Nutrition, exercise, water, and sleep</h2><p>There is no single meal plan for every body. A useful plate includes a source of protein, plants, and a satisfying carbohydrate. Strength exercise preserves muscle during weight loss and supports function during aging. Water needs vary with weather, food, activity, pregnancy, and health conditions; drink regularly and seek clinical advice if you have fluid restrictions. Sleep is often overlooked: a steady sleep schedule can support appetite regulation, energy, and recovery.</p><h2>How to use this healthy weight calculator</h2><p>Enter your age, sex, height, and weight. Choose metric or imperial units. The BMI calculator immediately displays your BMI value, category, and an estimated healthy-weight range for your height. Use the result as a point of orientation. If you have a chronic condition, are pregnant, are under 18, have had recent unexplained weight change, or are considering major changes to food or exercise, discuss the result with a qualified professional.</p></article></Section><Section eyebrow="Answers, plainly stated" title="BMI calculator FAQs"><FAQ items={faqs}/></Section><Section eyebrow="Editorial standards" title="Reviewed health information, with sources."><div className="prose-health max-w-4xl"><p><strong>Written by Elena Morris, Certified Health Content Writer.</strong> Medically reviewed by <strong>Dr. Daniel Chen, MD</strong>, a licensed physician. Last reviewed July 24, 2026. Our editorial process prioritizes primary public-health guidance and clinically established sources; medical content is reviewed for accuracy and updated when guidance changes.</p><h3>References</h3><ul><li><a href="https://www.cdc.gov/bmi/about/index.html" className="text-teal-700 underline">Centers for Disease Control and Prevention: About BMI</a></li><li><a href="https://www.who.int/data/gho/data/themes/topics/topic-details/GHO/body-mass-index" className="text-teal-700 underline">World Health Organization: Body mass index</a></li><li><a href="https://www.nhs.uk/common-health-questions/lifestyle/what-is-the-body-mass-index-bmi/" className="text-teal-700 underline">NHS: What is BMI?</a></li></ul></div></Section></>}
